[tikz]
\begin{tikzpicture}[scale=0.42]
\coordinate (A) at (0,0);
\coordinate (B) at (12,0);
\coordinate (C) at (4,7);
\draw (A)--(B)--(C)--cycle;
\draw[dashed] (C)--(4,0);
\draw (4.4,0)--(4.4,0.4)--(4,0.4);
\node[below,font=\small] at (6,0) {$12\text{ cm}$};
\node[right,font=\small] at (4,3.5) {$7\text{ cm}$};

\end{tikzpicture}
[/tikz]
Find the area of this triangle.
Give your answer in $\text{cm}^{2}$.

[tikz]
\begin{tikzpicture}[scale=0.34]
\coordinate (A) at (0,0);
\coordinate (B) at (14,0);
\coordinate (C) at (0,5);
\draw (A)--(B)--(C)--cycle;
\draw (0.6,0)--(0.6,0.6)--(0,0.6);
\node[below,font=\small] at (7,0) {$14\text{ m}$};
\node[left,font=\small] at (0,2.5) {$5\text{ m}$};

\end{tikzpicture}
[/tikz]
Find the area of this right-angled triangle.
Give your answer in $\text{m}^{2}$.

[tikz]
\begin{tikzpicture}[scale=0.4]
\coordinate (A) at (0,0);
\coordinate (B) at (16,0);
\coordinate (C) at (-5,5);
\draw (A)--(B)--(C)--cycle;
\draw[dashed] (-5,0)--(A);
\draw[dashed] (C)--(-5,0);
\draw (-4.6,0)--(-4.6,0.4)--(-5,0.4);
\node[below,font=\small] at (8,0) {$16\text{ cm}$};
\node[left,font=\small] at (-5,2.5) {$5\text{ cm}$};
\end{tikzpicture}
[/tikz]
The perpendicular height is measured to the dashed extension of the base.
Find the area of this triangle.
Give your answer in $\text{cm}^{2}$.

[tikz]
\begin{tikzpicture}[scale=0.5,every node/.style={font=\normalsize}]
\coordinate (A) at (0,0);
\coordinate (B) at (10,0);
\coordinate (C) at ({sqrt(28)},6);
\coordinate (H) at ({sqrt(28)},0);
\draw (A)--(B)--(C)--cycle;
\draw[dashed] (C)--(H);
\draw ({sqrt(28)+0.35},0)--({sqrt(28)+0.35},0.35)--({sqrt(28)},0.35);
\node[below] at (5,0) {$10\text{ cm}$};
\node[right] at ({sqrt(28)},3) {$6\text{ cm}$};
\node[above left] at ({sqrt(28)/2},3) {$8\text{ cm}$};
\end{tikzpicture}
[/tikz]
Find the area of this triangle.
Give your answer in $\text{cm}^{2}$.

[tikz]
\begin{tikzpicture}[scale=0.3]
\coordinate (A) at (0,0);
\coordinate (B) at (18,0);
\coordinate (C) at (24,7);
\coordinate (D) at (6,7);
\draw (B)--(C)--(D)--(A);
\draw (A)--(B);
\draw[dashed] (D)--(6,0);
\draw (6.4,0)--(6.4,0.4)--(6,0.4);
\node[below,font=\small] at (9,0) {$18\text{ mm}$};
\node[right,font=\small] at (6,3.5) {$7\text{ mm}$};

\end{tikzpicture}
[/tikz]
This parallelogram is cut along a diagonal into two identical triangles.
Find the area of one triangle in $\text{mm}^{2}$.

[tikz]
\begin{tikzpicture}[scale=0.5]
\coordinate (A) at (0,0);
\coordinate (B) at (9,0);
\coordinate (C) at (4,5);
\draw (A)--(B)--(C)--cycle;
\draw[dashed] (C)--(4,0);
\draw (4.4,0)--(4.4,0.4)--(4,0.4);
\node[below,font=\small] at (4.5,0) {$9\text{ km}$};
\node[right,font=\small] at (4,2.5) {$5\text{ km}$};

\end{tikzpicture}
[/tikz]
Find the area of this triangle.
Give your answer in $\text{km}^{2}$.

[tikz]
\begin{tikzpicture}[scale=0.2]
\draw (0,0)--(20,0)--(13,9)--cycle;
\draw (13,9)--(14,0);
\draw[dashed] (13,9)--(13,0);
\draw (12,0)--(12,1)--(13,1);
\node[below,font=\small] at (7,0) {$14\text{ m}$};
\node[below,font=\small] at (17,0) {$6\text{ m}$};
\node[left,font=\small,fill=white,inner sep=1pt] at (13,4.5) {$9\text{ m}$};
\end{tikzpicture}
[/tikz]
A line from the top corner splits the base into two parts.
Find the difference between the areas of the two smaller triangles, in $\text{m}^{2}$.
